export interface ConnectorConfig {
  /** Asana Personal Access Token from the Asana Developer Console */
  asanaPersonalAccessToken: string
  /** Asana Workspace GID where the task will be created */
  asanaWorkspaceGid: string
  /** Optional Asana Project GID to associate the task with a project */
  asanaProjectGid?: string
  /** Optional Asana user GID to assign the task */
  asanaAssigneeGid?: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface JotformSubmission {
  id: string
  title: string
  flat: Record<string, string>
  answers: Record<string, string>
}

export interface CreateTaskResult {
  taskId: string
  taskName: string
  taskNotes: string
}

function buildTaskName(flat: Record<string, string>): string {
  const first = flat.first_name?.trim()
  const last = flat.last_name?.trim()
  if (first && last) return `${first} ${last}`
  if (first) return first
  if (last) return last
  return 'Jotform Submission'
}

function buildTaskNotes(flat: Record<string, string>, answers: Record<string, string>): string {
  const lines: string[] = []
  if (flat.email) lines.push(`Email: ${flat.email}`)
  const answerEntries = Object.entries(answers)
  if (answerEntries.length > 0) {
    const answersStr = answerEntries.map(([k, v]) => `${k}: ${v}`).join(', ')
    lines.push(`Answers: ${answersStr}`)
  }
  return lines.join('\n')
}

async function parseJotformPayload(rawBody: string): Promise<JotformSubmission> {
  let parsed: unknown
  try {
    parsed = JSON.parse(rawBody)
  } catch {
    throw new Error('Invalid JSON in Jotform webhook payload')
  }

  const payload = parsed as Record<string, unknown>

  if (payload.rawRequest && typeof payload.rawRequest === 'string') {
    try {
      const inner = JSON.parse(payload.rawRequest) as Record<string, unknown>
      return validateSubmission(inner)
    } catch {
      throw new Error('Invalid JSON in Jotform rawRequest field')
    }
  }

  return validateSubmission(payload)
}

function validateSubmission(payload: Record<string, unknown>): JotformSubmission {
  if (!payload.id || typeof payload.id !== 'string') {
    throw new Error('Missing required field: id')
  }
  if (!payload.flat || typeof payload.flat !== 'object' || payload.flat === null) {
    throw new Error('Missing required field: flat')
  }
  if (!payload.answers || typeof payload.answers !== 'object' || payload.answers === null) {
    throw new Error('Missing required field: answers')
  }
  return {
    id: payload.id,
    title: typeof payload.title === 'string' ? payload.title : 'Untitled Form',
    flat: payload.flat as Record<string, string>,
    answers: payload.answers as Record<string, string>,
  }
}

export async function handle(
  payload: string | JotformSubmission,
  config: ConnectorConfig,
): Promise<CreateTaskResult> {
  const fetchImpl = config.fetch ?? fetch

  let submission: JotformSubmission
  if (typeof payload === 'string') {
    submission = await parseJotformPayload(payload)
  } else {
    submission = validateSubmission(payload as Record<string, unknown>)
  }

  const taskName = buildTaskName(submission.flat)
  const taskNotes = buildTaskNotes(submission.flat, submission.answers)

  const body: Record<string, unknown> = {
    data: {
      workspace: config.asanaWorkspaceGid,
      name: taskName,
      notes: taskNotes,
    },
  }

  if (config.asanaProjectGid) {
    body.data.projects = [config.asanaProjectGid]
  }
  if (config.asanaAssigneeGid) {
    body.data.assignee = config.asanaAssigneeGid
  }

  const response = await fetchImpl('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.asanaPersonalAccessToken}`,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(
      `Asana API error: ${response.status} ${response.statusText} for POST https://app.asana.com/api/1.0/tasks - ${text}`,
    )
  }

  const result = (await response.json()) as { data: { gid: string; name: string; notes: string } }
  return {
    taskId: result.data.gid,
    taskName: result.data.name,
    taskNotes: result.data.notes,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, JotformSubmission } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  type RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      asanaPersonalAccessToken: 'test-token',
      asanaWorkspaceGid: '67890',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.taskId).toBe('987654321')
    expect(result.taskName).toBe('John Doe')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let mockFetch: typeof fetch
  let calls: RecordedCall[]

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.method === 'POST' && req.url === 'https://app.asana.com/api/1.0/tasks') {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    mockFetch = fetch
    calls = recordedCalls
    baseConfig = {
      asanaPersonalAccessToken: 'test-token',
      asanaWorkspaceGid: '67890',
      fetch: mockFetch,
    }
  })

  it('creates a task with mapped fields from flat and answers', async () => {
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, baseConfig)
    expect(result.taskId).toBe('987654321')
    expect(result.taskName).toBe('John Doe')
    expect(result.taskNotes).toContain('Email: john.doe@example.com')
    expect(result.taskNotes).toContain('text-123: John')
    expect(result.taskNotes).toContain('text-456: Doe')
    expect(result.taskNotes).toContain('email-789: john.doe@example.com')
  })

  it('sends correct request body to Asana', async () => {
    await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, baseConfig)
    expect(calls).toHaveLength(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://app.asana.com/api/1.0/tasks')
    expect(call.headers.get('authorization')).toBe('Bearer test-token')
    expect(call.headers.get('content-type')).toBe('application/json')
    const body = call.json as { data: { workspace: string; name: string; notes: string } }
    expect(body.data.workspace).toBe('67890')
    expect(body.data.name).toBe('John Doe')
    expect(body.data.notes).toContain('Email: john.doe@example.com')
  })

  it('includes project and assignee when configured', async () => {
    const configWithExtras: ConnectorConfig = {
      ...baseConfig,
      asanaProjectGid: 'project-123',
      asanaAssigneeGid: 'user-456',
    }
    await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, configWithExtras)
    const body = calls[0].json as { data: { projects?: string[]; assignee?: string } }
    expect(body.data.projects).toEqual(['project-123'])
    expect(body.data.assignee).toBe('user-456')
  })

  it('parses multipart payload with rawRequest field', async () => {
    const multipartPayload = JSON.stringify({
      rawRequest: JSON.stringify(SOURCE_EXAMPLE),
    })
    const result = await handle(multipartPayload, baseConfig)
    expect(result.taskId).toBe('987654321')
  })

  it('throws on missing id field', async () => {
    const badPayload = { ...SOURCE_EXAMPLE, id: undefined }
    await expect(handle(badPayload as unknown as JotformSubmission, baseConfig)).rejects.toThrow(
      'Missing required field: id',
    )
  })

  it('throws on missing flat field', async () => {
    const badPayload = { ...SOURCE_EXAMPLE, flat: undefined }
    await expect(handle(badPayload as unknown as JotformSubmission, baseConfig)).rejects.toThrow(
      'Missing required field: flat',
    )
  })

  it('throws on missing answers field', async () => {
    const badPayload = { ...SOURCE_EXAMPLE, answers: undefined }
    await expect(handle(badPayload as unknown as JotformSubmission, baseConfig)).rejects.toThrow(
      'Missing required field: answers',
    )
  })

  it('throws on non-2xx response from Asana', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ errors: [{ message: 'Unauthorized' }] }, 401))
    const config = { ...baseConfig, fetch }
    await expect(handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config)).rejects.toThrow(
      'Asana API error: 401 Unauthorized for POST https://app.asana.com/api/1.0/tasks',
    )
    expect(errorCalls).toHaveLength(1)
  })

  it('uses default name when first_name and last_name are missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      flat: { email: 'test@example.com' },
      answers: { 'field-1': 'value1' },
    }
    const result = await handle(payload as unknown as JotformSubmission, baseConfig)
    expect(result.taskName).toBe('Jotform Submission')
  })

  it('handles empty answers object', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      flat: { first_name: 'Jane', last_name: 'Smith', email: 'jane@example.com' },
      answers: {},
    }
    const result = await handle(payload as unknown as JotformSubmission, baseConfig)
    expect(result.taskName).toBe('Jane Smith')
    expect(result.taskNotes).toBe('Email: jane@example.com')
  })
})

